fn solve(input: Vec<char>) -> Vec<char> {
    // Copy so we can trim in-place
    let mut s = input;

    // Step 1: remove a single trailing newline if present
    if matches!(s.last(), Some('\n')) {
        s.pop();
    }

    // Helper: define whitespace as specified
    fn is_ws(c: char) -> bool {
        matches!(c, ' ' | '\t' | '\n' | '\r')
    }

    // Step 2: repeatedly remove leading/trailing whitespace until stable
    // (Equivalent to trimming both ends.)
    while let Some(&c) = s.first() {
        if is_ws(c) {
            s.remove(0);
        } else {
            break;
        }
    }
    while let Some(&c) = s.last() {
        if is_ws(c) {
            s.pop();
        } else {
            break;
        }
    }

    // Step 3: validate password rules
    let mut has_lower = false;
    let mut has_upper = false;
    let mut has_digit = false;

    for &c in &s {
        if ('a'..='z').contains(&c) {
            has_lower = true;
        } else if ('A'..='Z').contains(&c) {
            has_upper = true;
        } else if ('0'..='9').contains(&c) {
            has_digit = true;
        }
    }

    let valid = s.len() >= 5 && has_lower && has_upper && has_digit;

    if valid {
        "Correct\n".chars().collect()
    } else {
        "Too weak\n".chars().collect()
    }
}